mapper.select:
SELECT * FROM pf.personal_memory WHERE space_id=#{actor.spaceId} AND owner_user_id=#{actor.userId}
 AND status=#{status}
 AND workspace_id=#{workspace}
 AND pf.authorize_workspace_actor(#{actor.userId},#{actor.spaceId}) ORDER BY created_at DESC,id LIMIT 500

mapper.update:
WITH changed AS (UPDATE pf.personal_memory SET status='SUPERSEDED',revision=revision+1,updated_at=clock_timestamp()
  WHERE space_id=#{actor.spaceId} AND owner_user_id=#{actor.userId} AND status='ACTIVE' AND scope_kind=#{target.scopeKind}
   AND workspace_id IS NOT DISTINCT FROM #{target.workspaceId} AND topic_key=#{target.topicKey} AND id<>#{target.id}
  RETURNING id,space_id,owner_user_id,revision,content_sha256)
  INSERT INTO pf.personal_memory_audit(id,space_id,owner_user_id,memory_id,action,revision,content_sha256)
   SELECT gen_random_uuid(),space_id,owner_user_id,id,'SUPERSEDE',revision,content_sha256 FROM changed
